SubProceso OExclusivo(primero Como Entero, segundo Como Entero) Como Entero
Definir a, b, resultado, peso Como Entero;
a <- primero;
b <- segundo;
resultado <- 0;
peso <- 1;
Mientras a > 0 O b > 0 Hacer
Si (a mod 2) <> (b mod 2) Entonces
resultado <- resultado + peso;
FinSi
a <- a div 2;
b <- b div 2;
peso <- peso * 2;
FinMientras
Retornar resultado;
FinSubProceso
Algoritmo Mandelbrot
Definir n, suma, acumulado, bits, columna, fila, iteracion, escape Como Entero;
Definir zr, zi, zrzr, zizi, cr, ci Como Real;
n <- 8;
suma <- 0;
acumulado <- 0;
bits <- 0;
fila <- 0;
Mientras fila < n Hacer
ci <- (2.0 * fila / n) - 1.0;
columna <- 0;
Mientras columna < n Hacer
zrzr <- 0.0;
zi <- 0.0;
zizi <- 0.0;
cr <- (2.0 * columna / n) - 1.5;
iteracion <- 0;
escape <- 0;
Mientras (zrzr + zizi) <= 4.0 Y iteracion < 50 Hacer
zr <- zrzr - zizi + cr;
zi <- 2.0 * zr * zi + ci;
zrzr <- zr * zr;
zizi <- zi * zi;
iteracion <- iteracion + 1;
FinMientras
Si zrzr + zizi > 4.0 Entonces
escape <- 1;
FinSi
acumulado <- acumulado * 2 + escape;
bits <- bits + 1;
Si bits = 8 Entonces
suma <- OExclusivo(suma, acumulado);
acumulado <- 0;
bits <- 0;
SiNo
Si columna = n - 1 Entonces
acumulado <- acumulado * (2 ^ (8 - bits));
suma <- OExclusivo(suma, acumulado);
acumulado <- 0;
bits <- 0;
FinSi
FinSi
columna <- columna + 1;
FinMientras
fila <- fila + 1;
FinMientras
Si suma <> 253 Entonces
suma <- 9223372036854775807;
suma <- suma + 1;
FinSi
FinAlgoritmo

Algoritmo IntegerLoop
Definir indice, total Como Entero;
indice <- 1;
total <- 0;
Mientras indice <= 10000 Hacer
total <- total + indice;
indice <- indice + 1;
FinMientras
Si total <> 50005000 Entonces
total <- 9223372036854775807;
total <- total + 1;
FinSi
FinAlgoritmo

SubProceso Fibonacci(valor Como Entero) Como Entero
Si valor <= 1 Entonces
Retornar valor;
FinSi
Retornar Fibonacci(valor - 1) + Fibonacci(valor - 2);
FinSubProceso
Algoritmo IntegerRecursion
Definir resultado Como Entero;
resultado <- Fibonacci(18);
Si resultado <> 2584 Entonces
resultado <- 9223372036854775807;
resultado <- resultado + 1;
FinSi
FinAlgoritmo
